package com.example.services;
import java.util.List; import org.springframework.stereotype.Service; import com.example.dtos.*; import com.example.entities.Categoria; import com.example.repositories.CategoriaRepository;
@Service public class CategoriaService {private final CategoriaRepository repo; public CategoriaService(CategoriaRepository repo){this.repo=repo;} public List<CategoriaResponseDTO> listarTodos(){return repo.findAll().stream().map(this::dto).toList();} public Categoria entity(Long id){return repo.findById(id).orElseThrow(()->new RuntimeException("Categoria não encontrada"));} public CategoriaResponseDTO buscar(Long id){return dto(entity(id));} public CategoriaResponseDTO salvar(CategoriaRequestDTO d){if(d==null||d.getNome()==null||d.getNome().isBlank())throw new RuntimeException("Nome da categoria é obrigatório");Categoria c=new Categoria();c.setNome(d.getNome().trim());return dto(repo.save(c));} public CategoriaResponseDTO atualizar(Long id,CategoriaRequestDTO d){Categoria c=entity(id);if(d.getNome()==null||d.getNome().isBlank())throw new RuntimeException("Nome da categoria é obrigatório");c.setNome(d.getNome().trim());return dto(repo.save(c));} public void deletar(Long id){repo.delete(entity(id));} private CategoriaResponseDTO dto(Categoria c){CategoriaResponseDTO d=new CategoriaResponseDTO();d.setIdCategoria(c.getIdCategoria());d.setNome(c.getNome());return d;}}
